INSERT INTO subjects (id, subject_code, subject_name, credits, description, department_id) VALUES
(1, 'BS101', 'Giải tích 1', 3, 'Giới hạn, đạo hàm, vi phân và tích phân hàm một biến', 1),
(2, 'BS102', 'Đại số tuyến tính', 3, 'Ma trận, định thức, hệ phương trình tuyến tính và không gian vector', 1),
(3, 'BS103', 'Vật lý đại cương 1', 3, 'Cơ học chất điểm, nhiệt học và trường tĩnh điện', 3),
(4, 'BS104', 'Triết học Mác - Lênin', 3, 'Chủ nghĩa duy vật biện chứng và chủ nghĩa duy vật lịch sử', 2),
(5, 'BS105', 'Pháp luật đại cương', 2, 'Những vấn đề cơ bản về nhà nước và pháp luật Việt Nam', 2),
(6, 'IT101', 'Nhập môn lập trình', 3, 'Nguyên lý tư duy lập trình căn bản với ngôn ngữ C/C++', 1),
(7, 'IT201', 'Lập trình Java nâng cao', 3, 'Lập trình hướng đối tượng, Collections, Generics và Stream API', 1),
(8, 'IT202', 'Cơ sở dữ liệu', 3, 'Mô hình quan hệ thực thể ERD, chuẩn hóa 3NF và truy vấn SQL', 1),
(9, 'IT203', 'Cấu trúc dữ liệu & Giải thuật', 3, 'Danh sách liên kết, Cây nhị phân, Đồ thị và giải thuật quy hoạch động', 1),
(10, 'IT301', 'Phát triển ứng dụng Web', 3, 'Fullstack Web: ReactJS, Vite, Spring Boot REST API và JWT', 1),
(11, 'IT302', 'Mạng máy tính', 3, 'Mô hình OSI, giao thức TCP/UDP, địa chỉ IP và định tuyến Router', 1),
(12, 'IT303', 'Trí tuệ nhân tạo căn bản', 3, 'Học máy Machine Learning, mạng nơ-ron và Computer Vision', 1),
(13, 'IT304', 'Kỹ thuật phần mềm', 3, 'Quy trình Agile/Scrum, thiết kế mẫu Design Patterns và CI/CD', 1),
(14, 'IT305', 'Kiểm thử phần mềm', 3, 'Kiểm thử hộp trắng, hộp đen, tự động hóa Selenium và JUnit', 1),
(15, 'IT401', 'An toàn thông tin', 3, 'Mã hóa RSA, chữ ký điện tử, an ninh mạng và chống tấn công web', 1),
(16, 'BA101', 'Nguyên lý quản trị', 3, 'Hoạch định, tổ chức, lãnh đạo và kiểm soát trong tổ chức', 2),
(17, 'BA102', 'Kinh tế vi mô', 3, 'Quy luật cung cầu, co giãn giá cả và phân tích thị trường cạnh tranh', 2),
(18, 'BA103', 'Kinh tế vĩ mô', 3, 'Lạm phát, thất nghiệp, tăng trưởng GDP và chính sách tài khóa', 2),
(19, 'BA201', 'Quản trị Marketing', 3, 'Hành vi người tiêu dùng, chiến lược sản phẩm, định giá và xúc tiến', 2),
(20, 'BA202', 'Kế toán tài chính', 3, 'Hệ thống tài khoản kế toán, bảng cân đối kế toán và báo cáo lưu chuyển', 2),
(21, 'BA301', 'Quản trị tài chính doanh nghiệp', 3, 'Định giá dòng tiền, chi phí vốn WACC và quản lý rủi ro đầu tư', 2),
(22, 'BA302', 'Quản trị nhân lực', 3, 'Tuyển dụng, đào tạo, đãi ngộ và văn hóa doanh nghiệp', 2),
(23, 'EE101', 'Kỹ thuật điện đại cương', 3, 'Mạch điện một chiều, xoay chiều 3 pha và máy biến áp', 3),
(24, 'EE201', 'Mạch điện tử và vi xử lý', 4, 'Transistor, khuếch đại thuật toán Op-Amp và vi điều khiển STM32', 3),
(25, 'EE202', 'Hệ thống điều khiển tự động', 3, 'Lý thuyết điều khiển tự động, hàm truyền đạt và bộ điều khiển PID', 3),
(26, 'EE301', 'Cảm biến và đo lường điện', 3, 'Các loại cảm biến công nghiệp và mạch chuyển đổi tín hiệu đo', 3),
(27, 'EE302', 'Hệ thống nhúng và IoT', 3, 'Lập trình ESP32, giao thức MQTT và kết nối Cloud IoT', 3),
(28, 'ME101', 'Cơ học kỹ thuật', 3, 'Tĩnh học vật rắn, động học và động lực học cơ hệ', 4),
(29, 'ME201', 'Vẽ kỹ thuật & CAD 3D', 3, 'Tiêu chuẩn ISO bản vẽ kỹ thuật và thiết kế 3D SolidWorks', 4),
(30, 'ME202', 'Kỹ thuật động cơ ô tô', 4, 'Chu trình nhiệt, hệ thống phun xăng điện tử EFI và chẩn đoán OBD', 4),
(31, 'ME301', 'Sức bền vật liệu', 3, 'Kéo nén đúng tâm, uốn phẳng và tính toán độ bền kết cấu', 4),
(32, 'ME302', 'Công nghệ chế tạo máy CNC', 3, 'Phương pháp gia công tiện, phay CNC và lập trình G-Code', 4),
(33, 'EN101', 'Tiếng Anh giao tiếp học thuật', 2, 'Kỹ năng nghe nói, phản xạ và thuyết trình tiếng Anh tự tin', 5),
(34, 'EN201', 'Tiếng Anh chuyên ngành CNTT', 3, 'Thuật ngữ tin học, dịch tài liệu API và viết tài liệu kỹ thuật', 5),
(35, 'JA101', 'Tiếng Nhật sơ cấp 1', 3, 'Bảng chữ cái Hiragana, Katakana, ngữ pháp căn bản Minna no Nihongo', 5);
